"""Generate command examples and availability from the authoritative CLI registry."""

from __future__ import annotations

import argparse
import json
import shlex
from pathlib import Path

from polyforge.commands import COMMANDS, CONTRACT_VERSION

ROOT = Path(__file__).resolve().parents[1]


def documents() -> dict[Path, str]:
    """Produce exact documentation and fixture content for every command."""
    lines = [
        "# CLI command contract",
        "",
        f"Contract version: {CONTRACT_VERSION}",
        "",
        "Generated by `python -m tools.generate_cli_docs`; edit the command registry.",
        "",
        "Only capability list/show/run are implemented in Phase 0. All other",
        "examples are syntax fixtures, not evidence of execution or functionality.",
        "",
        "| Command | Availability | Example |",
        "| --- | --- | --- |",
    ]
    examples = []
    for spec in COMMANDS:
        example = "polyforge " + shlex.join(spec.example)
        availability = "Implemented" if spec.implemented else f"NOT_RUN; Phase {spec.phase}"
        lines.append(f"| `{' '.join(spec.path)}` | {availability} | `{example}` |")
        examples.append(
            {"argv": list(spec.example), "implemented": spec.implemented, "phase": spec.phase}
        )
    lines.extend(
        [
            "",
            "## Status and process exit",
            "",
            "Tool statuses: PASS, FAIL, BLOCKED, NOT_RUN, REVIEW.",
            "Game acceptance: ACCEPTED, PARTIAL, REJECTED; independent from tool status.",
            "The operation_status field always equals status. evaluated_test_status",
            "describes actual tests separately; listing metadata runs no gameplay tests.",
            "",
            "| Exit | Meaning |",
            "| --- | --- |",
            "| 0 | Successful operation |",
            "| 2 | Invalid input |",
            "| 3 | Missing dependency |",
            "| 4 | Policy denied or review required |",
            "| 5 | Producer failure or operation not implemented |",
            "| 6 | Contract/invariant failure |",
            "| 7 | Test failure |",
            "| 8 | Retry exhausted |",
            "| 9 | Interrupted |",
            "",
            "No failed, blocked, pending-review, or unexecuted operation exits zero.",
            "A successful read-only query may describe tests that were not run.",
            "Canonical build stages are S0 through S5; aliases are not accepted.",
            "report requires both --workspace and --run-id. init uses a positional",
            "new directory; doctor and init do not require an existing workspace.",
            "",
        ]
    )
    return {
        ROOT / "docs/cli.md": "\n".join(lines),
        ROOT / "tests/fixtures/cli_commands.json": json.dumps(
            {"contract_version": CONTRACT_VERSION, "commands": examples}, indent=2
        )
        + "\n",
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for path, content in documents().items():
        if args.check:
            if not path.is_file() or path.read_text("utf-8") != content:
                stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
    if stale:
        print("Stale CLI generated files: " + ", ".join(stale))
        return 1
    print("CLI documentation is current" if args.check else "Generated CLI docs and fixtures")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
